/**
 * [TimingPieces] on real songs: for each, the sheet's line times, where
 * [LyricsWordAlign] placed each line in Deepgram whisper-large's whole-song
 * transcript, how much of it matched, and how many letters it has. Numbers only,
 * no lyric. The expected answers are from the measure the design was picked on
 * (11-06, scored against whisper-medium and scripts/synctest.py).
 */
class TimingPiecesRealDataTest {

    private class Song(
        val name: String,
        val times: String,
        val starts: String,
        val shares: String,
        val letters: String,
        val sizes: List<Int>?,
        val rate: Double?,
        val overrules: Boolean?,
        val values: String?,
        val lastHeardMs: Long,
    ) {
        val timeList = times.split(',').map { it.toLong() }
        val placed = timeList.indices.map { i ->
            TimingPieces.Placed(
                timeMs = timeList[i],
                startMs = starts.split(',')[i].toLong().takeIf { it >= 0L },
                share = shares.split(',')[i].toDouble(),
                letters = letters.split(',')[i].toInt(),
            )
        }
    }

