    @Test
    fun `the stretches found on real songs are the ones measured`() {
        for (song in songs) {
            val outcome = TimingPieces.fit(song.placed, song.lastHeardMs)
            val found = outcome.result
            if (song.sizes == null) {
                assertNull(found, "${song.name} should be refused, got ${found?.sizes}")
                continue
            }
            assertNotNull(found, "${song.name} refused: ${outcome.refused}")
            assertEquals(song.sizes, found.sizes, song.name)
            assertEquals(song.rate!!, found.rate, 0.001, song.name)
            val values = song.values!!.split(',').map { it.toLong() }
            song.timeList.forEachIndexed { i, t ->
                assertTrue(abs(found.map.map(t) - values[i]) <= 5L, "${song.name} line $i: ${found.map.map(t)} vs ${values[i]}")
            }
        }
    }

    @Test
    fun `a straight line stands unless real structure overrules it`() {
        for (song in songs) {
            val expected = song.overrules ?: continue
            val points = song.placed.filter { it.letters > 0 && it.startMs != null }.map { it.timeMs to it.startMs!! }
            val line = assertNotNull(TimingFit.fit(points), song.name)
            val found = assertNotNull(TimingPieces.fit(song.placed, song.lastHeardMs).result, song.name)
            assertEquals(expected, TimingPieces.overrules(line.map, found), song.name)
        }
    }

    @Test
    fun `no real wrong sheet gets a map`() {
        val wrong = songs.filter { it.name.contains('/') }
        assertTrue(wrong.size >= 6)
        for (song in wrong) assertNull(TimingPieces.fit(song.placed, song.lastHeardMs).result, song.name)
    }
